function isThree(n) {
  const root = Math.round(Math.sqrt(n));
  if (root * root !== n) {
    return false;
  }
  if (root < 2) {
    return false;
  }
  for (let d = 2; d * d <= root; d++) {
    if (root % d === 0) {
      return false;
    }
  }
  return true;
}

